import logging
import sys
logging.basicConfig(level=logging.INFO, format='%(levelname)s:%(message)s', stream=sys.stdout)

def processar_valores(lista):
    validos = []
    for i, s in enumerate(lista):
        try:
            v = float(s)
            validos.append(v)
        except Exception as e:
            logging.warning(f"Índice {i}: valor inválido '{s}': {e}")
    return validos
